import{_ as e,o as a,c as r,a0 as s}from"./chunks/framework.BQvjZmTX.js";const h=JSON.parse('{"title":"Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundaries.md","filePath":"explanation/boundaries.md"}'),o={name:"explanation/boundaries.md"};function n(i,t,d,c,l,p){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h1><p>arca is one organism in a stack — it owns <strong>secret materialization</strong> and nothing else. If a feature needs another kind of memory or authority, it belongs to a neighbor.</p><table tabindex="0"><thead><tr><th>neighbor</th><th>owns</th><th>how it meets arca</th></tr></thead><tbody><tr><td><strong>myco</strong></td><td>work memory — tasks, issues, proposals, plans, ADRs, handoffs</td><td>this repo&#39;s <code>project/</code> ledger is myco&#39;s; arca has no PM surface</td></tr><tr><td><strong>sturn</strong></td><td>ephemeral coordination — live claims/ops/topics</td><td>not secrets: sturn state is transient, arca state is sealed</td></tr><tr><td><strong>kuda</strong></td><td>code memory — symbol/index knowledge</td><td>arca refs name <em>secrets</em>, not code entities</td></tr><tr><td><strong>peregrin</strong></td><td>orchestration — campaigns, multi-actor arbitration, policy</td><td>campaigns consume secrets via <code>arca run</code>; audit aggregation + real policy are peregrin&#39;s (<code>ARCA_ACTOR</code> is self-claimed inside arca); <code>arca serve</code> — the ndjson IPC wire + <code>[serve.pdp]</code> exec consult (ADR-0003) — is its embedding point</td></tr><tr><td><strong>bupha</strong></td><td>CI gate</td><td>asserts no plaintext secrets land in pipelines; <code>arca check</code> in pipeline steps</td></tr><tr><td><strong>mimus</strong></td><td>critic</td><td>secrets resolve env → arca → legacy (keyring, <code>~/.config/mimus/env</code>) via <code>mimus-arca</code> shelling <code>arca</code>; vaults are canonical, writes land in them</td></tr><tr><td><strong>sepia</strong></td><td>session lifecycle</td><td>session wrappers can capture arca&#39;s stderr audit stream</td></tr></tbody></table><h2 id="what-that-means-in-practice" tabindex="-1">What that means in practice <a class="header-anchor" href="#what-that-means-in-practice" aria-label="Permalink to &quot;What that means in practice&quot;">​</a></h2><ul><li><strong>A hosted vault service is in scope</strong> — <code>arca-vault-cf</code> is a store impl behind the same port, ciphertext-only, self-hosted.</li><li><strong>A daemon is out of scope</strong> — persistent coordination, multi-machine views, arbitration between actors → peregrin. arca stays a sync, embeddable binary: env vars are the interface, no SDK.</li><li><strong>Policy is out of scope</strong> — <code>[guardrails]</code> are advisory accident prevention. Enforcement, identity, and unforgeable attribution are orchestration concerns.</li><li><strong>The audit wire stops at stderr</strong> — emitting ndjson is arca&#39;s; collecting, storing, and alerting on it is peregrin&#39;s (ADR-0001 deliberately removed the local <code>audit.jsonl</code>).</li></ul>',5)])])}const g=e(o,[["render",n]]);export{h as __pageData,g as default};
